function l(n,r=new Date){if(n==null||n==="")return{label:"never",tone:"neutral"};const t=new Date(n).getTime();if(Number.isNaN(t))return{label:"never",tone:"neutral"};const a=Math.max(0,r.getTime()-t),e=Math.floor(a/60/6e4),o=e<1?"<1h ago":e<48?`${e}h ago`:`${Math.floor(e/24)}d ago`;return a>=1728e5?{label:`${o} · stale`,tone:"warning"}:{label:`${o} · ok`,tone:"success"}}export{l as b};
